// ═══════════════════════════════════════════════════════════════

async function main() {
  console.log('══════════════════════════════════════════════════════════════');
  console.log('  ADD ASSESSMENTS + KNOWLEDGE CHECKS');
  console.log('══════════════════════════════════════════════════════════════\n');

  await mongoose.connect(MONGODB_URI);
  console.log('Connected to MongoDB\n');

  const db = mongoose.connection.db;
  const collection = db.collection('interactivecourses');
  
  let updated = 0;
  let totalQs = 0;
  let totalKCs = 0;

  for (const [slug, questions] of Object.entries(ASSESSMENTS)) {
    const course = await collection.findOne({ slug });
    if (!course) {
      console.log('  ⚠️  Not found:', slug);
      continue;
    }

    // Format questions
    const formatted = questions.map(q => ({
      text: q.q,
      question: q.q,
      type: 'multipleChoice',
      options: q.a.map((text, idx) => ({ text, isCorrect: idx === q.c })),
      explanation: q.e
    }));

    // Build assessment
    if (!course.assessment) {
      course.assessment = { questions: [], passThreshold: 0.8, maxAttempts: 3 };
    }

    // Add questions that don't already exist
    let added = 0;
    for (const q of formatted) {
      const exists = course.assessment.questions.some(existing => 
        existing.text === q.text || existing.question === q.text
      );
      if (!exists) {
        course.assessment.questions.push(q);
        added++;
      }
    }

    // Also add KCs to sections that don't have any
    let kcAdded = 0;
    if (course.sections) {
      let qIdx = 0;
      for (const sec of course.sections) {
        if (!sec.contentBlocks) continue;
        const hasKC = sec.contentBlocks.some(b => b.type === 'multipleChoice');
        if (!hasKC && qIdx < formatted.length) {
          sec.contentBlocks.push({
            type: 'multipleChoice',
            order: sec.contentBlocks.length,
            question: formatted[qIdx].text,
            options: formatted[qIdx].options,
            explanation: formatted[qIdx].explanation,
            feedbackCorrect: 'Correct! ' + formatted[qIdx].explanation,
            feedbackIncorrect: 'Not quite. ' + formatted[qIdx].explanation
          });
          kcAdded++;
          qIdx += 3; // Spread out across sections
        }
      }
    }

    const op = {};
    op["$set"] = { sections: course.sections, assessment: course.assessment, updatedAt: new Date() };
    await collection.updateOne({ _id: course._id }, op);

    const total = course.assessment.questions.length;
    console.log('  ✅', slug, '| +' + added + ' assessment Qs (total:', total + ') | +' + kcAdded, 'KCs');
    updated++;
    totalQs += added;
    totalKCs += kcAdded;
  }

  console.log('\n══════════════════════════════════════════════════════════════');
  console.log('  Courses updated:', updated);
  console.log('  Assessment Qs added:', totalQs);
  console.log('  Knowledge checks added:', totalKCs);
  console.log('══════════════════════════════════════════════════════════════\n');

  await mongoose.disconnect();
}

main().catch(err => { console.error('Error:', err.message); process.exit(1); });
